use soroban_sdk::{Address,BytesN,Env,Vec};use crate::types::*;use common::pause;
pub fn init(env:&Env,admin:&Address)->Result<(),EscrowError>{env.storage().instance().set(&DataKey::Admin,admin);env.storage().instance().set(&DataKey::NextSwapId,&0u64);env.storage().persistent().set(&DataKey::SwapRequests,&Vec::<SwapRequest>::new(env));Ok(())}
pub fn create_swap(env:&Env,initiator:&Address,responder:&Address,initiator_amount:i128,responder_amount:i128,hash_lock:BytesN<32>,time_lock:u64)->Result<u64,EscrowError>{pause::when_not_paused(env).map_err(|_|EscrowError::ContractPaused)?;let _guard=common::reentrancy::ReentrancyGuard::new(env).map_err(|_|EscrowError::NotInitialized)?;initiator.require_auth();if initiator==responder{return Err(EscrowError::InvalidSwap);}if initiator_amount<=0||responder_amount<=0{return Err(EscrowError::InvalidAmount);}let now=env.ledger().timestamp();if time_lock<=now{return Err(EscrowError::TimeLockExpired);}let next_id:u64=env.storage().instance().get(&DataKey::NextSwapId).unwrap_or(0);let swap=SwapRequest{id:next_id,initiator:initiator.clone(),responder:responder.clone(),initiator_amount,responder_amount,hash_lock,time_lock,status:STATUS_PENDING,created_at:now};let mut swaps:Vec<SwapRequest>=env.storage().persistent().get(&DataKey::SwapRequests).unwrap_or_else(||Vec::new(env));swaps.push_back(swap);env.storage().persistent().set(&DataKey::SwapRequests,&swaps);env.storage().instance().set(&DataKey::NextSwapId,&next_id.checked_add(1).ok_or(EscrowError::InvalidAmount)?);SwapCreated{id:next_id,initiator:initiator.clone(),responder:responder.clone(),initiator_amount,responder_amount}.publish(env);Ok(next_id)}
pub fn accept_swap(env:&Env,id:u64,responder:&Address,secret:BytesN<32>)->Result<(),EscrowError>{pause::when_not_paused(env).map_err(|_|EscrowError::ContractPaused)?;let _guard=common::reentrancy::ReentrancyGuard::new(env).map_err(|_|EscrowError::NotInitialized)?;responder.require_auth();let mut swaps:Vec<SwapRequest>=env.storage().persistent().get(&DataKey::SwapRequests).ok_or(EscrowError::NotInitialized)?;let mut found=false;for i in 0..swaps.len(){let mut s=swaps.get(i).ok_or(EscrowError::VecAccessError)?;if s.id==id{if s.status!=STATUS_PENDING{return Err(EscrowError::SwapNotActive);}if s.responder!=*responder{return Err(EscrowError::Unauthorized);}let secret_bytes=soroban_sdk::Bytes::from_array(env,&secret.to_array());let computed_hash=env.crypto().sha256(&secret_bytes).to_bytes();let hash_lock_array=s.hash_lock.to_array();if computed_hash!=hash_lock_array{return Err(EscrowError::HashLockMismatch);}let now=env.ledger().timestamp();if now>s.time_lock{return Err(EscrowError::TimeLockExpired);}s.status=STATUS_ACTIVE;swaps.set(i,s.clone());found=true;SwapAccepted{id,responder:responder.clone()}.publish(env);break;}}if!found{return Err(EscrowError::SwapNotFound);}env.storage().persistent().set(&DataKey::SwapRequests,&swaps);Ok(())}
pub fn complete_swap(env:&Env,id:u64,caller:&Address)->Result<(),EscrowError>{pause::when_not_paused(env).map_err(|_|EscrowError::ContractPaused)?;let _guard=common::reentrancy::ReentrancyGuard::new(env).map_err(|_|EscrowError::NotInitialized)?;caller.require_auth();let mut swaps:Vec<SwapRequest>=env.storage().persistent().get(&DataKey::SwapRequests).ok_or(EscrowError::NotInitialized)?;let mut found=false;for i in 0..swaps.len(){let mut s=swaps.get(i).ok_or(EscrowError::VecAccessError)?;if s.id==id{if s.status!=STATUS_ACTIVE{return Err(EscrowError::SwapNotActive);}if *caller!=s.initiator&&*caller!=s.responder{return Err(EscrowError::Unauthorized);}s.status=STATUS_COMPLETED;swaps.set(i,s.clone());found=true;SwapCompleted{id,initiator:s.initiator.clone(),responder:s.responder.clone()}.publish(env);break;}}if!found{return Err(EscrowError::SwapNotFound);}env.storage().persistent().set(&DataKey::SwapRequests,&swaps);Ok(())}
pub fn cancel_swap(env:&Env,id:u64,caller:&Address)->Result<(),EscrowError>{pause::when_not_paused(env).map_err(|_|EscrowError::ContractPaused)?;let _guard=common::reentrancy::ReentrancyGuard::new(env).map_err(|_|EscrowError::NotInitialized)?;caller.require_auth();let mut swaps:Vec<SwapRequest>=env.storage().persistent().get(&DataKey::SwapRequests).ok_or(EscrowError::NotInitialized)?;let mut found=false;for i in 0..swaps.len(){let mut s=swaps.get(i).ok_or(EscrowError::VecAccessError)?;if s.id==id{if s.status==STATUS_COMPLETED||s.status==STATUS_CANCELLED{return Err(EscrowError::SwapNotActive);}if *caller!=s.initiator&&*caller!=s.responder{return Err(EscrowError::Unauthorized);}s.status=STATUS_CANCELLED;swaps.set(i,s);found=true;SwapCancelled{id}.publish(env);break;}}if!found{return Err(EscrowError::SwapNotFound);}env.storage().persistent().set(&DataKey::SwapRequests,&swaps);Ok(())}
pub fn get_swap(env:&Env,id:u64)->Result<SwapRequest,EscrowError>{let swaps:Vec<SwapRequest>=env.storage().persistent().get(&DataKey::SwapRequests).ok_or(EscrowError::NotInitialized)?;for i in 0..swaps.len(){if let Some(s)=swaps.get(i){if s.id==id{return Ok(s);}}}Err(EscrowError::SwapNotFound)}
pub fn get_swaps(env:&Env)->Vec<SwapRequest>{env.storage().persistent().get(&DataKey::SwapRequests).unwrap_or_else(||Vec::new(env))}
pub fn pause(env:&Env,admin:&Address)->Result<(),EscrowError>{let s:Address=env.storage().instance().get(&DataKey::Admin).ok_or(EscrowError::NotInitialized)?;if admin!=&s{return Err(EscrowError::Unauthorized);}pause::pause(env,admin).map_err(|_|EscrowError::ContractPaused)}
pub fn unpause(env:&Env,admin:&Address)->Result<(),EscrowError>{let s:Address=env.storage().instance().get(&DataKey::Admin).ok_or(EscrowError::NotInitialized)?;if admin!=&s{return Err(EscrowError::Unauthorized);}pause::unpause(env,admin).map_err(|_|EscrowError::ContractPaused)}